import React, { ElementRef } from 'react';
import { SkeletonLoaderProps } from './SkeletonLoader.types';
import { StyledSkeletonContainer, StyledSkeletonImage } from './SkeletonLoader.styles';

const SkeletonLoader = React.forwardRef<
  ElementRef<typeof StyledSkeletonContainer>,
  SkeletonLoaderProps
>(
  (
    {
      width = '100%',
      height = '56px',
      imageShape = 'rectangle',
      variant = 'body',
      ...otherProps
    }: SkeletonLoaderProps,
    forwardRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => (
    <StyledSkeletonContainer
      css={{
        width,
        height,
        borderRadius: variant === 'image' && imageShape === 'circle' ? '$full' : '$1',
        backgroundColor: variant === 'image' ? 'none' : '$interfaceSurfacePrimary',
      }}
      ref={forwardRef}
      tabIndex={-1}
      {...otherProps}
    >
      {variant === 'image' && (
        <StyledSkeletonImage
          src="data:image/svg+xml;base64,"
          alt="skeleton loader"
        />
      )}
    </StyledSkeletonContainer>
  )
);

export default SkeletonLoader;
